{"hypotheses": [
  {
    "root_cause": "service:gridcast:forecast-pipeline",
    "mechanism": "The forecast-pipeline's own job/container is crash-looping or being OOM-killed due to a recent code or configuration change, so each run is interrupted and reported as held or failed.",
    "statement": "The fault originates inside the forecast-pipeline itself, not in an upstream dependency."
  },
  {
    "root_cause": "service:gridcast:postgres",
    "mechanism": "Postgres is experiencing slow queries, connection exhaustion, or lock contention, causing the forecast-pipeline's database reads/writes to time out and fail.",
    "statement": "The forecast pipeline is failing because required Postgres operations cannot complete successfully."
  },
  {
    "root_cause": "service:gridcast:feature-service",
    "mechanism": "Feature-service is returning errors or high latency for feature requests, causing the forecast-pipeline feature-fetch stage to exceed retry or timeout thresholds.",
    "statement": "The forecast pipeline is failing because its feature inputs from feature-service are missing, slow, or invalid."
  },
  {
    "root_cause": "service:gridcast:forecast-service",
    "mechanism": "Forecast-service is returning model inference errors or invalid response payloads, causing the pipeline's forecasting step to fail validation and abort.",
    "statement": "The forecast pipeline is failing because forecast-service inference is degraded."
  },
  {
    "root_cause": "service:gridcast:planning-api",
    "mechanism": "Planning-api is unavailable or erroring on plan/constraint requests, so forecast-pipeline cannot obtain required planning inputs and the run is held or fails.",
    "statement": "The forecast pipeline is failing because upstream planning-api is not serving the required plan data."
  }
]}
